print('snapshot entries', len(cmap), 'bad', bad, 'disk', disk, 'unlisted', unl[:10])
m = json.load(open(S + '/application-subject.v45.json'))
same = []; diff = []; absent = []
for e in m['files']:
    if e['path'] in cmap:
